//! Exact native schema replay inside exclusive full-dataset restore custody.
//!
//! The pinned native exporter emits every persisted field, including children
//! automatically generated by an array/set/relation definition. Replaying a
//! parent recreates those placeholders. The later saved child definition is
//! authoritative: skipping it would lose its assertions, defaults or policy.

use std::collections::BTreeSet;

use surrealdb::sql::statements::DefineStatement;
use surrealdb::sql::{Query, Statement};

use crate::{StorageError, StorageResult};

pub(super) fn parsed_restore_query(sql: &str) -> StorageResult<Query> {
    let mut parsed =
        surrealdb::sql::parse(sql).map_err(|error| StorageError::QueryError(error.to_string()))?;
    let mut fields = BTreeSet::new();
    for statement in &mut parsed.0 .0 {
        if let Statement::Define(DefineStatement::Field(field)) = statement {
            if !fields.insert((field.what.0.clone(), field.name.to_string())) {
                return Err(StorageError::DataIntegrityError(
                    "native snapshot repeats an explicit field definition".into(),
                ));
            }
            // This changes only the definition-conflict behavior in a freshly
            // replaced database. All actual saved field clauses remain intact;
            // ordinary queries and definition validation are unchanged.
            field.overwrite = true;
        }
    }
    Ok(parsed)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::recovery_barrier::RecoveryPhase;
    use crate::snapshot::{export_named, restore_named, SnapshotRetention};
    use crate::StorageClient;
    use serde_json::{json, Value};
    use std::time::Duration;

    #[test]
    #[expect(
        clippy::unwrap_used,
        reason = "Malformed fixture data or a failed operation must fail this regression at its original assertion site."
    )]
    fn restore_changes_only_unique_top_level_field_conflict_flags() {
        let sql = r"
            OPTION IMPORT;
            DEFINE TABLE restore_schema SCHEMAFULL;
            DEFINE FIELD provenance ON restore_schema FLEXIBLE TYPE object;
            DEFINE FIELD provenance.chain ON restore_schema TYPE array<object>;
            DEFINE FIELD provenance.chain.* ON restore_schema FLEXIBLE TYPE object;
            DEFINE FIELD provenance.chain.*.kind ON restore_schema TYPE string
                ASSERT $value = 'original' COMMENT 'saved child constraint';
            DEFINE FIELD immutable ON restore_schema TYPE string READONLY DEFAULT 'initial';
            DEFINE FIELD computed ON restore_schema TYPE string VALUE string::lowercase($value)
                PERMISSIONS FOR select WHERE space_id = 'private';
            CREATE restore_schema:original SET immutable='DEFINE FIELD harmless ON prose TYPE string',
                provenance={chain:[{kind:'original'}]}, computed='MiXeD';
            OPTION IMPORT = FALSE;
        ";
        let original = surrealdb::sql::parse(sql).unwrap();
        let restored = parsed_restore_query(sql).unwrap();
        assert_eq!(original.0 .0.len(), restored.0 .0.len());
        let mut changed_fields = 0;
        for (before, after) in original.0 .0.iter().zip(&restored.0 .0) {
            match (before, after) {
                (
                    Statement::Define(DefineStatement::Field(before)),
                    Statement::Define(DefineStatement::Field(after)),
                ) => {
                    assert!(!before.overwrite);
                    assert!(after.overwrite);
                    let mut expected = before.clone();
                    expected.overwrite = true;
                    assert_eq!(after, &expected, "saved field clauses must not be dropped");
                    changed_fields += 1;
                }
                _ => assert_eq!(
                    before, after,
                    "data and non-field statements must be identical"
                ),
            }
        }
        assert_eq!(changed_fields, 6);
    }

    #[test]
    fn ambiguous_duplicate_saved_fields_are_rejected_instead_of_last_write_wins() {
        for sql in [
            "DEFINE FIELD value ON probe TYPE int; DEFINE FIELD value ON probe TYPE string;",
            "DEFINE FIELD values.* ON probe TYPE int; DEFINE FIELD OVERWRITE values[*] ON probe TYPE int;",
            "DEFINE FIELD `value` ON probe TYPE int; DEFINE FIELD IF NOT EXISTS value ON probe TYPE int;",
        ] {
            assert!(matches!(parsed_restore_query(sql), Err(StorageError::DataIntegrityError(_))));
        }
        assert!(parsed_restore_query(
            "DEFINE FIELD value ON first TYPE int; DEFINE FIELD value ON second TYPE string;"
        )
        .is_ok());
    }

    #[expect(
        clippy::unwrap_used,
        reason = "Malformed fixture data or a failed operation must fail this regression at its original assertion site."
    )]
    async fn stored_fields(client: &StorageClient) -> Value {
        let mut response = client
            .query_checked("INFO FOR TABLE restore_schema_probe")
            .await
            .unwrap();
        let info: Option<Value> = response.take(0).unwrap();
        info.unwrap()["fields"].clone()
    }

    #[expect(
        clippy::unwrap_used,
        reason = "Malformed fixture data or a failed operation must fail this regression at its original assertion site."
    )]
    async fn stored_row(client: &StorageClient) -> Option<Value> {
        let mut response = client
            .query_checked(
                "SELECT space_id, provenance, nested, note, immutable FROM ONLY restore_schema_probe:original",
            )
            .await
            .unwrap();
        response.take(0).unwrap()
    }

    #[tokio::test]
    #[expect(
        clippy::significant_drop_tightening,
        reason = "Keep fixture resources and guards alive through the original assertions and scope cleanup."
    )]
    #[expect(
        clippy::too_many_lines,
        reason = "Keep the complete ordered conformance scenario and its failure assertions together."
    )]
    #[expect(
        clippy::unwrap_used,
        reason = "Malformed fixture data or a failed operation must fail this regression at its original assertion site."
    )]
    async fn actual_native_named_backup_restores_full_nested_schema_and_replaces_dataset() {
        let client = StorageClient::new_memory().await.unwrap();
        client
            .query_checked(
                r"
            DEFINE TABLE restore_schema_probe SCHEMAFULL;
            DEFINE FIELD space_id ON restore_schema_probe TYPE string;
            DEFINE FIELD provenance ON restore_schema_probe FLEXIBLE TYPE object;
            DEFINE FIELD provenance.chain ON restore_schema_probe TYPE array<object>;
            DEFINE FIELD OVERWRITE provenance.chain.* ON restore_schema_probe FLEXIBLE TYPE object;
            DEFINE FIELD provenance.chain.*.kind ON restore_schema_probe TYPE string
                ASSERT $value = 'original' COMMENT 'saved child constraint';
            DEFINE FIELD nested ON restore_schema_probe TYPE array<array<int>>;
            DEFINE FIELD OVERWRITE nested.*.* ON restore_schema_probe TYPE int
                ASSERT $value > 0 COMMENT 'saved nested numeric constraint';
            DEFINE FIELD note ON restore_schema_probe TYPE string VALUE string::lowercase($value)
                PERMISSIONS FOR select WHERE space_id = 'schema-space';
            DEFINE FIELD immutable ON restore_schema_probe TYPE string READONLY DEFAULT 'retained-default';
            CREATE restore_schema_probe:original SET space_id='schema-space',
                provenance={chain:[{kind:'original',extra:'retained'}]}, nested=[[1,2],[3]],
                note='DEFINE FIELD is preserved inside data';
        ",
            )
            .await
            .unwrap();
        let fields = stored_fields(&client).await;
        let row = stored_row(&client).await.unwrap();
        assert_eq!(row["nested"], json!([[1, 2], [3]]));
        assert_eq!(row["immutable"], "retained-default");
        assert_eq!(row["provenance"]["chain"][0]["extra"], "retained");
        let directory = tempfile::tempdir().unwrap();
        let backup = directory.path().join("actual-native-export");
        let original_journal = client.erasure_journal().unwrap().identity().to_owned();
        let manifest = export_named(
            &client,
            &backup,
            "nested-schema",
            &SnapshotRetention::default(),
        )
        .await
        .unwrap();
        assert_eq!(manifest.journal_id, original_journal);
        // This is the real native exporter, including its saved implicit child
        // field definitions. No hand-built snapshot or manufactured journal.
        let exported = std::fs::read_to_string(backup.join("data.snapshot")).unwrap();
        assert!(exported.contains("provenance.chain[*]"));
        assert!(exported.contains("nested[*][*]"));
        client
            .query_checked(
                r"
            UPDATE restore_schema_probe:original SET nested=[[7]], note='newer value';
            DEFINE TABLE post_backup_only SCHEMALESS;
            CREATE post_backup_only:canary SET space_id='schema-space', must_disappear=true;
        ",
            )
            .await
            .unwrap();
        restore_named(&client, &backup, client.erasure_journal().unwrap())
            .await
            .unwrap();
        assert!(client.recovery_status().ready);
        assert_eq!(
            client.erasure_journal().unwrap().identity(),
            original_journal
        );
        assert_eq!(
            stored_fields(&client).await,
            fields,
            "all original field clauses must survive native replay"
        );
        assert_eq!(stored_row(&client).await, Some(row));
        let mut tables = client.query_checked("INFO FOR DB").await.unwrap();
        let info: Option<Value> = tables.take(0).unwrap();
        assert!(info.unwrap()["tables"].get("post_backup_only").is_none());
        let rejected = client
            .query_checked(
                r"
            CREATE restore_schema_probe:invalid SET space_id='schema-space',
                provenance={chain:[{kind:'original'}]}, nested=[[0]], note='invalid nested value';
        ",
            )
            .await
            .unwrap_err();
        assert!(
            rejected.to_string().contains("nested"),
            "restored child assertion must cause the rejection: {rejected}"
        );
        let mut response = client
            .query_checked("SELECT VALUE note FROM restore_schema_probe:invalid")
            .await
            .unwrap();
        let values: Vec<String> = response.take(0).unwrap();
        assert!(values.is_empty());
        let readonly = client
            .query_checked("UPDATE restore_schema_probe:original SET immutable='changed'")
            .await
            .unwrap_err();
        assert!(
            readonly.to_string().contains("immutable"),
            "saved READONLY field must still reject change: {readonly}"
        );
        client
            .query_checked(
                r"
            CREATE restore_schema_probe:defaults SET space_id='schema-space',
                provenance={chain:[{kind:'original'}]}, nested=[[9]], note='MixedCase';
        ",
            )
            .await
            .unwrap();
        let mut response = client
            .query_checked("SELECT immutable, note FROM ONLY restore_schema_probe:defaults")
            .await
            .unwrap();
        let defaults: Option<Value> = response.take(0).unwrap();
        let defaults = defaults.unwrap();
        assert_eq!(defaults["immutable"], "retained-default");
        assert_eq!(defaults["note"], "mixedcase");
    }

    #[tokio::test]
    #[expect(
        clippy::significant_drop_tightening,
        reason = "Keep fixture resources and guards alive through the original assertions and scope cleanup."
    )]
    #[expect(
        clippy::unwrap_used,
        reason = "Malformed fixture data or a failed operation must fail this regression at its original assertion site."
    )]
    async fn duplicate_definition_refusal_precedes_destructive_database_replacement() {
        let client = StorageClient::new_memory().await.unwrap();
        client
            .query_checked("CREATE restore_original_sentinel:kept SET value='must-survive'")
            .await
            .unwrap();
        let guard = client
            .begin_maintenance(RecoveryPhase::Restoring, Duration::from_secs(5))
            .await
            .unwrap();
        let privileged = client.maintenance_client_with_guard(&guard);
        let result = privileged.replace_snapshot_bytes(
            b"OPTION IMPORT; DEFINE FIELD value ON duplicate_field TYPE int; DEFINE FIELD value ON duplicate_field TYPE string;"
        ).await;
        assert!(matches!(result, Err(StorageError::DataIntegrityError(_))));
        let malformed = privileged
            .replace_snapshot_bytes(b"DEFINE FIELD invalid ON")
            .await;
        assert!(matches!(malformed, Err(StorageError::QueryError(_))));
        let mut response = privileged
            .query_checked("SELECT VALUE value FROM restore_original_sentinel:kept")
            .await
            .unwrap();
        let values: Vec<String> = response.take(0).unwrap();
        assert_eq!(values, vec!["must-survive"]);
        guard.finish();
        assert!(client.recovery_status().ready);
    }

    #[tokio::test]
    #[expect(
        clippy::significant_drop_tightening,
        reason = "Keep fixture resources and guards alive through the original assertions and scope cleanup."
    )]
    #[expect(
        clippy::unwrap_used,
        reason = "Malformed fixture data or a failed operation must fail this regression at its original assertion site."
    )]
    async fn unrelated_native_restore_statement_error_remains_fatal_and_not_ready() {
        let client = StorageClient::new_memory().await.unwrap();
        let guard = client
            .begin_maintenance(RecoveryPhase::Restoring, Duration::from_secs(5))
            .await
            .unwrap();
        let privileged = client.maintenance_client_with_guard(&guard);
        let error = privileged.replace_snapshot_bytes(
            b"OPTION IMPORT; DEFINE TABLE restore_failure_probe SCHEMALESS; THROW 'unrelated_restore_fault';"
        ).await.unwrap_err();
        assert!(error.to_string().contains("unrelated_restore_fault"));
        assert!(!client.recovery_status().ready);
        drop(guard);
        assert!(
            !client.recovery_status().ready,
            "failed replacement cannot reopen ordinary access"
        );
    }
}
